def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    # Early game: cooperate, retaliate if opponent defects
    if n < 10:
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    # Counts
    opp_c = 0
    opp_d = 0
    my_d = 0
    for (a, b) in history:
        if b == 'C':
            opp_c += 1
        else:
            opp_d += 1
        if a == 'D':
            my_d += 1

    # If opponent never defected
    if opp_d == 0:
        if n < 15:
            return 'C'
        return 'D'

    # If opponent always defected
    if opp_c == 0:
        return 'D'

    my_last, opp_last = history[-1]

    # Conditional stats
    opp_c_after_my_D = 0
    opp_d_after_my_D = 0
    opp_c_after_my_C = 0
    opp_d_after_my_C = 0
    for i in range(1, n):
        my_prev = history[i-1][0]
        opp_curr = history[i][1]
        if my_prev == 'D':
            if opp_curr == 'C':
                opp_c_after_my_D += 1
            else:
                opp_d_after_my_D += 1
        else:
            if opp_curr == 'C':
                opp_c_after_my_C += 1
            else:
                opp_d_after_my_C += 1

    total_after_my_D = opp_c_after_my_D + opp_d_after_my_D
    total_after_my_C = opp_c_after_my_C + opp_d_after_my_C

    # Exploit forgiving opponent
    if total_after_my_D >= 1:
        forgiveness = opp_c_after_my_D / total_after_my_D
        if forgiveness > 0.8:
            return 'D'

    # If opponent is very aggressive
    if total_after_my_C >= 5:
        aggression = opp_d_after_my_C / total_after_my_C
        if aggression > 0.4:
            return 'D'

    # Forgive first defection if opponent has high cooperation rate
    if opp_d == 1 and opp_c > 0.8 * n:
        return 'C'

    # Opponent defection streak
    opp_streak = 0
    for i in range(n-1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    # Probe after long defection streak
    if opp_last == 'D' and my_last == 'C' and opp_streak >= 3:
        return 'D'

    # Default: Tit-for-Tat with apology
    if opp_last == 'D':
        if my_last == 'D':
            return 'C'
        else:
            if my_d > 0 and n >= 2 and history[-2][0] == 'D':
                return 'C'
            return 'D'
    else:
        return 'C'
